p = sys.argv[1]; go = len(sys.argv) > 2 and sys.argv[2] == 'go'
s = open(p, encoding='utf-8').read()
def sha(t): return hashlib.sha256(t.encode('utf-8')).hexdigest()[:8]
A = json.loads(r'''[["...d.staff.map(s => ({ id: s.id, name: s.name }))]", "...apShow(d).map(s => ({ id: s.id, name: s.name }))] /* (2.99.577) the techs chosen on this device */"], ["const cw = Math.floor(avail / Math.min(n, perScreen)), heads", "const cw = apZoomW(Math.floor(avail / Math.min(n, perScreen))) /* (2.99.577) - / + */, heads"], ["  fitCols(); nsMore(grid); nsOne(grid); stickNames();", "  apBar(d); /* (2.99.577) */ fitCols(); nsMore(grid); nsOne(grid); apNames(grid); stickNames();"], ["${tlabel(a.start)} \u2013 ${tlabel(a.start + a.duration)} \u00b7 ${esc(tech)}", "${tlabel(a.start)} \u2013 ${tlabel(a.start + a.duration)} \u00b7 ${a.duration} min \u00b7 ${esc(tech)}"], ["is the default\n  } catch (e) { oops(e); loadDay(false); }\n}\n", "is the default\n  } catch (e) { oops(e); loadDay(false); }\n}\n\n/* (2.99.577 - LENH 577, anh Logan 31/10 01:49) Appointments with many techs - owner + manager only (Desk / techs: no change):\n   1) zoom the columns: - / + (3 steps: fit the screen / ~140 px / ~200 px); wider than the screen -> the grid scrolls sideways, the times stay left, the names stay on top (both sticky as before)\n   2) which techs show: '\\ud83d\\udc65 All techs \\u25be' -> tick techs (techs with bookings first) + 'Only techs with appointments'; press and HOLD a name on top = only that tech (hold again = all); ANYONE always shows when a booking has no tech\n   3) remembered on this device (localStorage, try/catch) - a new day keeps it\n   4) a narrow box: only the customer's name on one line ('...') + the status colour; everything (services, time, MINUTES, tech, status) in the box one tap shows */\nconst AP7 = { key: 'nfApCols', w: [0, 140, 200], st: null, fit: 0 };\nAP7.on = () => !IS_DESK && (IS_MGR || document.documentElement.dataset.app === 'admin');\nAP7.get = () => { if (AP7.st) return AP7.st; let o = null; try { o = JSON.parse(localStorage.getItem(AP7.key) || 'null'); } catch (e) {}\n  o = o && typeof o === 'object' ? o : {}; AP7.st = { z: [0, 1, 2].includes(o.z) ? o.z : 0, hide: Array.isArray(o.hide) ? o.hide.map(Number).filter(Boolean) : [], only: !!o.only, solo: +o.solo || 0 }; return AP7.st; };\nAP7.save = () => { try { localStorage.setItem(AP7.key, JSON.stringify(AP7.get())); } catch (e) {} };\nAP7.busy = (d) => { const m = new Map(); (d.appts || []).forEach(a => { if (a.status === 'cancelled' || a.status === 'noshow' || a.status === 'no_show') return; m.set(a.staff, (m.get(a.staff) || 0) + 1); }); return m; };\n/** the techs that get a column (renderGrid) - every booking still knows its tech (ANYONE stays for bookings with no tech) */\nfunction apShow(d) { const L = (d && d.staff) || []; if (!AP7.on() || !L.length) return L; const st = AP7.get();\n  if (st.solo) { const one = L.filter(s => s.id === st.solo); if (one.length) return one; }\n  const busy = AP7.busy(d); let r = L.filter(s => !st.hide.includes(s.id)); if (!r.length) r = L;\n  if (st.only) { const b = r.filter(s => busy.has(s.id)); if (b.length) r = b; } /* a day with no bookings yet: the ticked techs */\n  return r; }\n/** fitCols: the column width for the zoom step (never narrower than 'fit the screen') */\nfunction apZoomW(cw) { AP7.fit = cw; if (!AP7.on()) return cw; const z = AP7.get().z; apZoomBtns(); return z ? Math.max(cw, AP7.w[z]) : cw; }\nfunction apZoomBtns() { const b = $('#apCols'); if (!b) return; const z = AP7.get().z;\n  const mi = $('[data-apz=\"-1\"]', b), pl = $('[data-apz=\"1\"]', b); if (mi) mi.disabled = z <= 0; if (pl) pl.disabled = z >= 2 || AP7.fit >= AP7.w[z + 1]; }\nfunction apRedraw() { const w = $('#gridWrap'), g = $('#grid'); const fx = w && g && g.offsetWidth > w.clientWidth ? (w.scrollLeft + w.clientWidth / 2) / g.offsetWidth : 0, y = w ? w.scrollTop : 0;\n  hidePeek(); renderGrid(false); if (w) { w.scrollTop = y; const g2 = $('#grid'); if (fx && g2) w.scrollLeft = Math.max(0, fx * g2.offsetWidth - w.clientWidth / 2); } }\nfunction apLabel(d) { const st = AP7.get(), L = (d && d.staff) || [];\n  if (st.solo) { const t = L.find(s => s.id === st.solo); if (t) return { t: '\\ud83d\\udc64 ' + t.name + ' \\u2715', on: 1 }; }\n  const n = apShow(d).length; return n < L.length ? { t: '\\ud83d\\udc65 ' + n + ' of ' + L.length + ' techs \\u25be', on: 1 } : { t: '\\ud83d\\udc65 All techs \\u25be', on: 0 }; }\n/** the small row on top of the grid: [techs] ......... [- zoom +] */\nfunction apBar(d) { if (!AP7.on()) return; let b = $('#apCols'); const wrap = $('#gridWrap'); if (!wrap) return;\n  if (!b) { b = document.createElement('div'); b.id = 'apCols'; b.className = 'ap-cols';\n    b.innerHTML = '<button type=\"button\" class=\"ap-tk\" id=\"apTk\" aria-haspopup=\"true\"></button><span class=\"ap-z\"><button type=\"button\" data-apz=\"-1\" aria-label=\"Narrower columns\">\\u2212</button><i aria-hidden=\"true\">\\ud83d\\udd0d</i><button type=\"button\" data-apz=\"1\" aria-label=\"Wider columns\">+</button></span>';\n    wrap.parentNode.insertBefore(b, wrap);\n    b.addEventListener('click', (e) => { const z = e.target.closest('[data-apz]'); if (z) { if (z.disabled) return; const st = AP7.get(); st.z = Math.max(0, Math.min(2, st.z + +z.dataset.apz)); AP7.save(); apRedraw(); return; }\n      if (e.target.closest('#apTk')) { const st = AP7.get(); if (st.solo) { st.solo = 0; AP7.save(); apRedraw(); return; } apPick(); } }); }\n  const l = apLabel(d), tk = $('#apTk', b); tk.textContent = l.t; tk.classList.toggle('on', !!l.on); b.hidden = false; }\n/** '\\ud83d\\udc65 All techs' -> the list to tick */\nfunction apPick() { const d = S.day; if (!d) return; apPickClose(); const st = AP7.get(), busy = AP7.busy(d);\n  const L = [...d.staff].sort((a, b) => (busy.has(b.id) ? 1 : 0) - (busy.has(a.id) ? 1 : 0)); const shown = new Set(apShow(d).map(s => s.id));\n  const box = document.createElement('div'); box.id = 'apPick'; box.className = 'ap-pick'; box.setAttribute('role', 'dialog');\n  box.innerHTML = `<label class=\"ap-row ap-only\"><input type=\"checkbox\" id=\"apOnly\"${st.only ? ' checked' : ''}><span>Only techs with appointments</span></label>` +\n    L.map(s => `<label class=\"ap-row\"><input type=\"checkbox\" data-aps=\"${s.id}\"${!st.hide.includes(s.id) ? ' checked' : ''}${st.only && !busy.has(s.id) ? ' disabled' : ''}><span>${esc(s.name)}</span><small>${busy.has(s.id) ? busy.get(s.id) + ' appt' + (busy.get(s.id) > 1 ? 's' : '') : ''}</small></label>`).join('') +\n    '<div class=\"ap-pf\"><button type=\"button\" class=\"btn small\" id=\"apAll\">Show all</button><button type=\"button\" class=\"btn small primary\" id=\"apDone\">Done</button></div>';\n  document.body.appendChild(box); const r = $('#apTk').getBoundingClientRect(); box.style.top = Math.round(r.bottom + 6) + 'px'; box.style.left = Math.max(8, Math.round(r.left)) + 'px';\n  box.addEventListener('change', (e) => { const i = e.target; if (i.id === 'apOnly') st.only = i.checked; else if (i.dataset.aps) { const id = +i.dataset.aps; st.hide = st.hide.filter(x => x !== id); if (!i.checked) st.hide.push(id); }\n    AP7.save(); apRedraw(); $$('[data-aps]', box).forEach(x => { x.disabled = st.only && !busy.has(+x.dataset.aps); }); });\n  box.addEventListener('click', (e) => { if (e.target.id === 'apDone') apPickClose(); if (e.target.id === 'apAll') { st.hide = []; st.only = false; st.solo = 0; AP7.save(); apPickClose(); apRedraw(); } });\n  setTimeout(() => document.addEventListener('pointerdown', apPickOut, true), 0); }\nfunction apPickOut(e) { if (!e.target.closest || !e.target.closest('#apPick, #apTk')) apPickClose(); }\nfunction apPickClose() { const b = $('#apPick'); if (b) b.remove(); document.removeEventListener('pointerdown', apPickOut, true); }\n/** press and HOLD a tech's name (0.6 s) = only that tech; hold again = every tech */\nfunction apNames(grid) { if (!AP7.on() || !S.geo) return; const cols = S.geo.cols;\n  $$('.ghead .sname', grid).forEach((n, i) => { const c = cols[i]; if (!c || !c.id) return; let t = 0, x0 = 0, y0 = 0;\n    const stop = () => { clearTimeout(t); t = 0; };\n    n.addEventListener('pointerdown', (e) => { x0 = e.clientX; y0 = e.clientY; stop(); t = setTimeout(() => { t = 0; const st = AP7.get(); st.solo = st.solo === c.id ? 0 : c.id; AP7.save(); try { navigator.vibrate && navigator.vibrate(15); } catch (x) {} apRedraw(); }, 600); });\n    n.addEventListener('pointermove', (e) => { if (t && (Math.abs(e.clientX - x0) > 8 || Math.abs(e.clientY - y0) > 8)) stop(); });\n    ['pointerup', 'pointercancel', 'pointerleave'].forEach(k => n.addEventListener(k, stop));\n    n.addEventListener('contextmenu', (e) => e.preventDefault()); }); }\n(() => { const s = document.createElement('style'); s.id = 'ap577css'; s.textContent = [\n  '.ap-cols{display:flex;align-items:center;justify-content:space-between;gap:8px;padding:3px 6px 5px;background:var(--ios-bg,#F2F2F7)}',\n  '.ap-cols[hidden]{display:none}',\n  '.ap-cols .ap-tk{border:0;border-radius:15px;background:#fff;color:#111;font:600 14px/1 -apple-system,BlinkMacSystemFont,sans-serif;padding:7px 11px;min-height:30px;max-width:62vw;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;box-shadow:0 1px 0 rgba(0,0,0,.12)}',\n  '.ap-cols .ap-tk.on{background:#007AFF;color:#fff}',\n  '.ap-cols .ap-z{display:flex;align-items:center;background:#fff;border-radius:15px;box-shadow:0 1px 0 rgba(0,0,0,.12)}',\n  '.ap-cols .ap-z i{font-style:normal;font-size:13px;padding:0 1px}',\n  '.ap-cols .ap-z button{border:0;background:transparent;color:#007AFF;font:600 21px/1 -apple-system,BlinkMacSystemFont,sans-serif;width:38px;min-height:30px;padding:0}',\n  '.ap-cols .ap-z button:disabled{color:#C7C7CC}',\n  '.ap-pick{position:fixed;z-index:300;width:min(300px,calc(100vw - 16px));max-height:min(420px,70vh);overflow:auto;background:#fff;border-radius:14px;box-shadow:0 10px 34px rgba(0,0,0,.25);padding:6px 0 0}',\n  '.ap-pick .ap-row{display:flex;align-items:center;gap:10px;padding:10px 14px;font-size:16px;color:#111;border-bottom:1px solid #EEE}',\n  '.ap-pick .ap-row input{width:20px;height:20px;margin:0;flex:0 0 auto}',\n  '.ap-pick .ap-row span{flex:1;min-width:0;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}',\n  '.ap-pick .ap-row small{color:#8E8E93;font-size:13px}',\n  '.ap-pick .ap-only{font-weight:600}',\n  '.ap-pick .ap-pf{display:flex;justify-content:space-between;gap:8px;padding:8px 10px;position:sticky;bottom:0;background:#fff}',\n  'html[data-app=\"admin\"] #grid .ghead .sname,html[data-app=\"manager\"] #grid .ghead .sname{-webkit-touch-callout:none;-webkit-user-select:none;user-select:none}',\n  /* 4) a narrow box: the name only (one line) + the status colour */\n  'html[data-app=\"admin\"] #grid.ns-narrow .appt .nstx > :not(.nm),html[data-app=\"manager\"] #grid.ns-narrow .appt .nstx > :not(.nm){display:none!important}',\n  'html[data-app=\"admin\"] #grid.ns-narrow .appt .nco,html[data-app=\"manager\"] #grid.ns-narrow .appt .nco{display:none!important}',\n  ':where(html.look-dark) .ap-cols{background:var(--ios-bg,#212136)}',\n  ':where(html.look-dark) .ap-cols .ap-tk:not(.on),:where(html.look-dark) .ap-cols .ap-z,:where(html.look-dark) .ap-pick,:where(html.look-dark) .ap-pick .ap-pf{background:#2C2C2E;color:#F2F2F7}',\n  ':where(html.look-dark) .ap-pick .ap-row{color:#F2F2F7;border-color:#3A3A3C}'\n].join('\\n'); document.head.appendChild(s); })();\n"]]''')
n = [s.count(a) for a, _ in A]
print(p, 'sha', sha(s), 'anchors', *n, 'already', 'AP7' in s)
if 'AP7' in s: sys.exit('STOP: already patched - nothing changed')
if n != [1] * len(A): sys.exit('STOP: an anchor is not found exactly once - nothing changed')
t = s
for a, b in A: t = t.replace(a, b)
if not go: print('NEW would be sha', sha(t)); sys.exit('check only - run again with: go')
bk = os.path.expanduser('~/app/old'); os.makedirs(bk, exist_ok=True); st = time.strftime('%m%d%H%M'); b = f'{bk}/appts.js.pre-577-{st}'
shutil.copy2(p, b); mode = os.stat(p).st_mode; open(p, 'w', encoding='utf-8').write(t); os.chmod(p, mode)
if shutil.which('node'):
    r = subprocess.run(['node', '--check', p], capture_output=True, text=True)
    if r.returncode: shutil.copy2(b, p); sys.exit('JS ERROR - put back: ' + r.stderr[:300])
print('NEW sha', sha(t), 'backup', b)
